import shutil
root=Path(__file__).parent
shutil.copyfile(root.parent.parent/'icons/icon-128.png',root/'logo.png')
css='''*{box-sizing:border-box}html,body{margin:0;padding:0}body{font-family:"Avenir Next",Avenir,sans-serif;color:#202228;background:#f7f5f3}.canvas{width:1280px;height:800px;position:relative;overflow:hidden;background:#f7f5f3}.canvas.dark{background:#16191e;color:#eef0f3}.brand{position:absolute;left:48px;top:24px;display:flex;align-items:center;gap:12px;font-size:24px;font-weight:800;letter-spacing:-.5px}.brand img{width:44px;height:44px;border-radius:7px}.version{font-size:12px;letter-spacing:1px;color:#a0112c;margin-left:7px;border:1px solid #dfb4be;padding:3px 7px;border-radius:4px}.dark .version{color:#ffb2c1;border-color:#68414c}.audience{position:absolute;right:48px;top:41px;font-size:12px;font-weight:700;letter-spacing:1.5px;color:#757780}h1{position:absolute;left:48px;top:94px;margin:0;font-size:48px;font-weight:800;letter-spacing:-1.7px;line-height:1.13}.subtitle{position:absolute;left:48px;top:157px;margin:0;font-size:23px;line-height:1.4;color:#62636a}.dark .subtitle,.dark .audience{color:#b7bdc7}.window{position:absolute;overflow:hidden;border:1px solid #d6d4d3;background:#fff;border-radius:10px;box-shadow:0 12px 25px rgba(52,38,40,.07)}.dark .window{border-color:#454a54;background:#191b20;box-shadow:none}.bar{height:28px;border-bottom:1px solid #dedcda;background:#eeecea;color:#616068;display:flex;align-items:center;padding:0 15px;font-size:11px;letter-spacing:.4px;font-weight:700;gap:14px}.dark .bar{background:#252a32;color:#c1c6cf;border-color:#454a54}.bar i{display:flex;gap:5px}.bar i b{height:5px;width:5px;border-radius:50%;background:#a3a0a1}.capture{display:block;width:1184px;height:auto}.footer{position:absolute;left:48px;right:48px;bottom:25px;border-top:1px solid #dddad7;padding-top:12px;display:flex;justify-content:space-between;font-size:12px;color:#6e6b70;letter-spacing:.2px}.dark .footer{border-color:#373c45;color:#a8afba}.footer strong{color:#a0112c;font-weight:700}.dark .footer strong{color:#ffb2c1}.annotation{position:absolute;font-weight:700;font-size:25px;line-height:1.2;letter-spacing:-.6px;color:#b40f2c}.annotation span{font-size:18px;font-weight:500;letter-spacing:0;display:block;margin-top:6px;line-height:1.4}.dark .annotation{color:#ffb2c1}.overlay{position:absolute;left:0;top:0;width:1280px;height:800px;pointer-events:none}.overlay path,.overlay ellipse{fill:none;stroke:#b40f2c;stroke-width:4;stroke-linecap:round;stroke-linejoin:round}.dark .overlay path,.dark .overlay ellipse{stroke:#ffb2c1}.control{position:absolute;display:block;box-shadow:0 12px 30px rgba(52,38,40,.13);border-radius:12px}.dark .control{box-shadow:0 12px 28px rgba(4,5,7,.25)}.eyebrow{position:absolute;font-size:13px;letter-spacing:1.5px;font-weight:800;color:#a0112c}.dark .eyebrow{color:#ffb2c1}.number{display:inline-grid;place-items:center;border:2px solid #b40f2c;border-radius:50%;height:37px;width:37px;margin-bottom:15px;font-size:20px}.feature{position:absolute;width:360px}.feature h2{margin:0;font-size:28px;font-weight:800;line-height:1.18;letter-spacing:-.7px}.feature p{font-size:20px;line-height:1.45;color:#62636a;margin:14px 0 0}.note{font-size:18px!important;color:#79767b!important}.section-line{position:absolute;left:48px;width:338px;height:1px;background:#ded8d7}.pick-copy{position:absolute;left:474px;top:580px;width:744px;font-size:21px;line-height:1.5;color:#62636a}.pick-copy b{color:#202228}'''
(root/'styles.css').write_text(css)
header='''<div class="brand"><img src="logo.png" alt="UH ProfCheck icon">UH ProfCheck <span class="version">V2</span></div><div class="audience">FOR UNIVERSITY OF HOUSTON STUDENTS</div>'''
def footer(n,label):return f'<div class="footer"><span>Illustrative course data · Extension UI shown at enlarged sizes</span><span><strong>{label}</strong> &nbsp; {n:02d} / 04</span></div>'
def window(img,left,top,width,height,scale=1184):return f'<div class="window" style="left:{left}px;top:{top}px;width:{width}px;height:{height}px"><div class="bar"><i><b></b><b></b><b></b></i>myUH / Class Search and Enroll</div><img class="capture" src="captures/{img}" style="width:{scale}px" alt="UH ProfCheck on an enrollment course table"></div>'
def svg(content,dark=False):
 color='#ffb2c1' if dark else '#b40f2c'
 return f'<svg class="overlay" viewBox="0 0 1280 800"><defs><marker id="arrow" markerWidth="9" markerHeight="9" refX="7" refY="4" orient="auto"><path d="M1 1L7 4L1 7" style="stroke:{color};stroke-width:1.5;fill:none"/></marker></defs>{content}</svg>'
def write(name,body,dark=False):
 (root/f'{name}.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><title>UH ProfCheck — Chrome Web Store image</title><link rel="stylesheet" href="styles.css"></head><body><main class="canvas'+(' dark' if dark else '')+'">'+header+body+'</main></body></html>')
write('01-professor-insights','''<h1>Know more before you enroll.</h1><p class="subtitle">Professor ratings, GPA, and withdrawal history—right in myUH.</p>'''+window('light-course.jpg',48,210,1184,535)+'''<div class="annotation" style="left:559px;top:285px">RateMyProfessors<br>+ CougarGrades</div>'''+svg('''<ellipse cx="231" cy="266" rx="70" ry="27"/><path d="M540 307 Q421 302 318 274" marker-end="url(#arrow)"/><ellipse cx="902" cy="584" rx="125" ry="49"/><path d="M806 330 Q897 366 902 520" marker-end="url(#arrow)"/>''')+footer(1,'Professor insights'))
write('02-dark-mode','''<h1>myUH, after dark.</h1><p class="subtitle">Dark pages, readable tables, and a toggle right on the page.</p>'''+window('dark-course.jpg',48,230,860,499,858)+'''<div class="eyebrow" style="left:947px;top:230px">ON-PAGE CONTROLS</div><img class="control" src="captures/dark-panel.jpg?v=2" alt="Ranking controls with dark mode on" style="left:947px;top:262px;width:285px;height:285px"><div class="annotation" style="left:947px;top:599px;width:283px">Turn it on once.<span>Keep browsing<br>in dark mode.</span></div>'''+svg('''<ellipse cx="1193" cy="504" rx="31" ry="24"/><path d="M1178 583 Q1202 567 1197 542" marker-end="url(#arrow)"/>''',True)+footer(2,'Dark mode'),True)
write('03-ranking-modes','''<h1>Choose what “best” means to you.</h1><p class="subtitle">Switch between three ranking modes while you browse.</p><div class="eyebrow" style="left:64px;top:251px">YOUR RANKING</div><img class="control" src="captures/light-panel.jpg?v=2" alt="Best Overall, Easiest A, and Lowest Risk ranking controls" style="left:64px;top:282px;width:354px;height:354px"><div class="annotation" style="left:474px;top:260px">The recommendation updates in place.</div><div class="window" style="left:474px;top:327px;width:746px;height:229px;border-radius:10px"><img src="captures/light-pick.jpg?v=2" alt="Best Overall recommendation beside professor insights" style="display:block;width:746px"></div><p class="pick-copy"><b>Best Overall</b> balances the available signals.<br><b>Easiest A</b> prioritizes GPA. <b>Lowest Risk</b> prioritizes withdrawals.</p>'''+svg('''<ellipse cx="604" cy="404" rx="123" ry="32"/><path d="M432 374 Q450 375 464 389" marker-end="url(#arrow)"/>''')+footer(3,'Ranking modes'))
write('04-seats-and-tba','''<h1>Catch the details before you enroll.</h1><p class="subtitle">Scarce seats and missing instructors are easier to spot.</p><div class="feature" style="left:48px;top:269px"><div class="number">1</div><h2>Notice when seats<br>are running low.</h2><p>See a quiet seat warning<br>beside the professor insights.</p><p class="note">Based on availability shown by myUH.</p></div><div class="section-line" style="top:507px"></div><div class="feature" style="left:48px;top:524px"><div class="number">2</div><h2>Instructor still TBA?</h2><p>Keep the course-wide GPA<br>and withdrawal context.</p></div><div class="window" style="left:504px;top:267px;width:728px;height:415px;border-radius:10px"><img src="captures/light-details.jpg?v=2" alt="Two seats left notice and course data for a TBA instructor" style="display:block;width:728px"></div>'''+svg('''<ellipse cx="800" cy="386" rx="72" ry="27"/><path d="M409 365 Q465 365 492 378" marker-end="url(#arrow)"/><ellipse cx="616" cy="625" rx="109" ry="27"/><path d="M410 619 Q452 627 492 627" marker-end="url(#arrow)"/>''')+footer(4,'Seats + unassigned instructors'))
(root/'05-small-promo.html').write_text('''<!doctype html><html><head><meta charset="utf-8"><title>UH ProfCheck — small promotional tile</title><style>*{box-sizing:border-box}html,body{margin:0}main{position:relative;width:440px;height:280px;overflow:hidden;background:#191c22;color:#f5f4f2;font-family:"Avenir Next",Avenir,sans-serif;border:1px solid #383d47}main:before{content:"";position:absolute;left:0;top:0;width:158px;height:280px;background:#f4f1ef}img{position:absolute;width:126px;height:126px;left:16px;top:76px;border-radius:10px}h1{position:absolute;left:184px;top:71px;font-weight:800;font-size:37px;line-height:1.02;letter-spacing:-1.3px;margin:0}p{position:absolute;left:184px;top:172px;font-size:15px;line-height:1.5;color:#c7cbd2;margin:0}.tag{position:absolute;right:22px;top:23px;font-weight:800;font-size:12px;color:#ffb2c1;letter-spacing:1px}.line{position:absolute;left:184px;bottom:41px;width:75px;height:4px;background:#c8102e}</style></head><body><main><img src="logo.png" alt="UH ProfCheck"><div class="tag">V2</div><h1>UH<br>ProfCheck</h1><p>Ratings. Grades.<br>Dark mode.</p><div class="line"></div></main></body></html>''')
